-- Route playerbots around The Crossroads instead of through it.
--
-- NOT a migration on purpose: this rewrites links 1525/1526 of the playerbot
-- travel graph by id. Check your own node ids before running it - on a
-- different graph these numbers mean something else entirely.
--
-- The town holds three travel nodes, one of them sitting 21 yards from a guard,
-- and every ground route across the Barrens went through them. The new link
-- keeps at least 84 yards from every guard spawn. It wins on cost without any
-- code change: the in-town links carry max_creature_2 = 55, which factionAnnoyance
-- turns into roughly a sevenfold penalty for a level 24 Alliance bot, while the
-- bypass carries none.

-- Wegpunkte: 76, Gesamtlaenge: 606 m
-- Geringster Abstand zu einer Wache: 84 m

DELETE FROM `ai_playerbot_travelnode_link` WHERE (node_id=1526 AND to_node_id=1525) OR (node_id=1525 AND to_node_id=1526);
DELETE FROM `ai_playerbot_travelnode_path` WHERE (node_id=1526 AND to_node_id=1525) OR (node_id=1525 AND to_node_id=1526);

